// HasOrganization applies the HasEdge predicate on the "organization" edge.
func HasOrganization() predicate.AirMasterWaybill {
	return predicate.AirMasterWaybill(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, OrganizationTable, OrganizationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrganizationWith applies the HasEdge predicate on the "organization" edge with a given conditions (other predicates).
func HasOrganizationWith(preds ...predicate.Organization) predicate.AirMasterWaybill {
	return predicate.AirMasterWaybill(func(s *sql.Selector) {
		step := newOrganizationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasAirline applies the HasEdge predicate on the "airline" edge.
func HasAirline() predicate.AirMasterWaybill {
	return predicate.AirMasterWaybill(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, AirlineTable, AirlineColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAirlineWith applies the HasEdge predicate on the "airline" edge with a given conditions (other predicates).
func HasAirlineWith(preds ...predicate.Airline) predicate.AirMasterWaybill {
	return predicate.AirMasterWaybill(func(s *sql.Selector) {
		step := newAirlineStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

