// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AirMasterWaybill) predicate.AirMasterWaybill {
	return predicate.AirMasterWaybill(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AirMasterWaybill) predicate.AirMasterWaybill {
	return predicate.AirMasterWaybill(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AirMasterWaybill) predicate.AirMasterWaybill {
	return predicate.AirMasterWaybill(sql.NotPredicates(p))
}
